function packForm(formSel, data = {})
{
  $(formSel).serializeArray().map(function(x){
    data[x.name] = x.value;
  });

  return data;
}

function populateForm(formSelector, data) {
  $.each(data, function(key, value){
    $('[name='+key+']', formSelector).val(value);
  });
}

function brDatetoUsa(datestring)
{
  var dateSplitted = datestring.split('/');
  return dateSplitted[2] + '-' + dateSplitted[1] + '-' + dateSplitted[0];
}

function usaDatetoBr(datestring)
{
  var dateSplitted = datestring.split('-');
  return dateSplitted[2] + '/' + dateSplitted[1] + '/' + dateSplitted[0];
}
// Retornando a data padrao EUA com dois digitos no ano
function converterToTwoDigit(dateComplet) {
    if (!dateComplet) return '';
    
    let parts = dateComplet.split('/');
    if (parts.length === 3) {
        return parts[0] + '/' + parts[1] + '/' + parts[2].slice(-2);
    }
    return dateComplet;
}


function dataAtualFormatada(dt){
  var data = new Date(dt),
      dia  = data.getDate().toString(),
      diaF = (dia.length == 1) ? '0'+dia : dia,
      mes  = (data.getMonth()+1).toString(), //+1 pois no getMonth Janeiro começa com zero.
      mesF = (mes.length == 1) ? '0'+mes : mes,
      anoF = data.getFullYear();
  return diaF+"/"+mesF+"/"+anoF;
}

function formattedCurrentDate() {
  const now = new Date();
  return now.getDate().toString().padStart(2, '0')
    + (now.getMonth() + 1).toString().padStart(2, '0')
    + now.getFullYear().toString();
}

function reloadTable(tableId) {
  $("#" + tableId).DataTable().ajax.reload();
}

function convertBrCoinToFloat(valor){

  if(valor === ""){
    valor =  0;
  }else{
    valor = valor.replace(".","");
    valor = valor.replace(",",".");
    valor = parseFloat(valor);
  }
  return valor;

}

function formatFloatToBrCoin(value) {
  let formatter = new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  });

  return formatter.format(value).replace('R$', '').trim();
}

//formatar valor real brasileiro
//funcao similar ao formatFloatToBrCoin
function convertToReal(number, options = {}) {
  const { moneySign = true } = options;

  if(Number.isNaN(number) || !number) return "need a number as the first parameter";

  if(typeof number === "string") { // n1
      number = Number(number);
  }

  let res;

  const config = moneySign ? {style: 'currency', currency: 'BRL'} : {minimumFractionDigits: 2};

  moneySign
  ? res = number.toLocaleString('pt-BR', config)
  : res = number.toLocaleString('pt-BR', config)

  const needComma = number => number <= 1000;
  if(needComma(number)) {
      res = res.toString().replace(".", ",");
  }

  return res; // n2
}

let AccountModule = (function () {
    let accountResource = new ResourceModel('conta');
    let $modalAccount = $('#modal-account');
    let columns = [
        {data: 'name', name: 'name'},
        {data: 'type', name: 'type'},
        {data: 'balance', name: 'balance'},
        {data: 'created_at', name: 'created_at'},
        {data: 'action', name: 'action', orderable: false, searchable: false, className: 'nowrap'},
    ];
    let accountTable = new SearaTable('account-table', 'conta/dataTable', columns, 'conta', 'contas');
    let accountId = $('#account-id');

    function index () {
        accountTable.loadTable();

        $('#create-account-btn').on('click', function () {
            showForm();
        });

        $('#form-save-btn').on('click', function () {
            let id = accountId.val();

            if ('' === id) {
                createAccount();
                return;
            }

            updateAccount(id);
        });
    }

    function createAccount() {
        let formData = packForm('#form-account');
        SearaLoader.showModal('Cadastrando conta...');

        accountResource.create(formData, function (response) {
            notify.response(response);
            $modalAccount.modal('hide');
            accountTable.reloadTable();
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    function archiveAccount(id) {
        swal({
            title: 'Atenção',
            text: 'A conta será arquivada, deseja continuar?',
            type: 'warning',
            showCancelButton: true
        }).then(function() {
            SearaLoader.showModal('Arquivando conta...');
            accountResource.delete(id, function (response) {
                notify.response(response);
                accountTable.reloadTable();
            }).fail(function (jqXHR) {
                notify.response(jqXHR.responseJSON);
            }).always(function(){
                SearaLoader.hideModal();
            });
        });
    }

    function editAccount(id) {
        SearaLoader.showModal("Carregando dados da conta...");
        accountResource.read(id, function (data) {
            showForm();
            populateForm('#form-account', data);
            accountId.val(id);
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    function updateAccount(id) {
        let formData = packForm('#form-account');
        SearaLoader.showModal('Cadastrando conta...');

        accountResource.update(id, formData, function (response) {
            notify.response(response);
            closeForm();
            accountTable.reloadTable();
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    function showForm() {
        accountId.val('');
        $('#form-account').trigger('reset');
        $modalAccount.modal('show');
    }

    function closeForm() {
        $modalAccount.modal('hide');
    }

    return {
        index: index,
        archiveAccount: archiveAccount,
        editAccount: editAccount
    };
})();

$(document).ready(function () {
    AccountModule.index();
});

function archiveAccount(id) {
    AccountModule.archiveAccount(id);
}

function editAccount(id) {
    AccountModule.editAccount(id);
}

